def answer_requests(index, requests):
    if not isinstance(index, dict):
        raise TypeError("index must be a dictionary")
    for code, description in index.items():
        if not isinstance(code, str) or not isinstance(description, str):
            raise TypeError("codes and descriptions must be strings")
        if not code or not description:
            raise ValueError("codes and descriptions must not be empty")
    if not isinstance(requests, list):
        raise TypeError("requests must be a list")

    responses = []
    for request in requests:
        if not isinstance(request, str):
            raise TypeError("requests must be strings")
        request = request.strip()
        if request == "HELP":
            responses.append("Send an asset code.")
        elif request == "PING":
            responses.append("READY")
        elif request in index:
            responses.append(f"{request}: {index[request]}")
        else:
            responses.append(f"UNKNOWN: {request}")
    return responses

